const baseData=()=>({schema:7,expenseCategories:DEFAULT_EXPENSE_CATEGORIES.map(c=>({...c})),userName:"Christian",theme:"midnight",privacy:false,currency:"MXN",notifications:false,reminderLeadDays:3,accounts:[{id:uid(),name:"Efectivo",type:"cash",balance:0},{id:uid(),name:"Banco",type:"bank",balance:0},{id:uid(),name:"Ahorros",type:"savings",balance:0}],transactions:[],budgets:[{id:uid(),categoryId:"expense-food",category:"Alimentación",limit:5000},{id:uid(),categoryId:"expense-transport",category:"Transporte",limit:2500},{id:uid(),categoryId:"expense-entertainment",category:"Entretenimiento",limit:2000}],goals:[]});
